import XCTest

final class FollowTests: XCTestCase {
    let logPath = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-j21g4tgj/uitest/log.txt"

    func log(_ s: String) {
        let line = s + "\n"
        if let h = FileHandle(forWritingAtPath: logPath) {
            h.seekToEndOfFile()
            h.write(line.data(using: .utf8)!)
            h.closeFile()
        } else {
            try? line.write(toFile: logPath, atomically: true, encoding: .utf8)
        }
    }

    func firstExisting(_ candidates: [XCUIElement], timeout: TimeInterval = 5) -> XCUIElement? {
        let end = Date().addingTimeInterval(timeout)
        repeat {
            for c in candidates where c.exists && c.isHittable { return c }
            RunLoop.current.run(until: Date().addingTimeInterval(0.5))
        } while Date() < end
        return nil
    }

    func testFollowNewfriend() throws {
        try? FileManager.default.removeItem(atPath: logPath)
        log("start")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(3)
        log("tree-before: " + String(app.debugDescription.prefix(4000)))

        let searchTab = firstExisting([
            app.tabBars.buttons["Search"],
            app.buttons["Search"],
            app.buttons.matching(NSPredicate(format: "label CONTAINS[c] 'search'")).firstMatch,
        ])
        guard let tab = searchTab else { log("no search tab"); XCTFail("no search tab"); return }
        tab.tap()
        sleep(2)
        log("tapped search tab")

        let field = firstExisting([
            app.searchFields.firstMatch,
            app.textFields.firstMatch,
        ])
        guard let f = field else { log("no search field"); XCTFail("no search field"); return }
        f.tap()
        sleep(1)
        f.typeText("newfriend.test")
        sleep(1)
        app.keyboards.buttons["search"].firstMatch.tap()
        sleep(4)
        log("typed query; tree: " + String(app.debugDescription.prefix(6000)))

        let result = firstExisting([
            app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS[c] 'newfriend.test'")).firstMatch,
        ], timeout: 10)
        guard let r = result else { log("no result for newfriend.test"); XCTFail("no result"); return }
        r.tap()
        sleep(4)
        log("opened profile; tree: " + String(app.debugDescription.prefix(6000)))

        let follow = firstExisting([
            app.buttons.matching(NSPredicate(format: "label == 'Follow'")).firstMatch,
        ], timeout: 10)
        guard let fb = follow else { log("no Follow button"); XCTFail("no follow button"); return }
        fb.tap()
        sleep(3)
        log("tapped Follow")
        log("after: " + String(app.debugDescription.prefix(6000)))
    }
}

