import XCTest

final class FollowTests: XCTestCase {
    let dir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-j21g4tgj/uitest"

    func log(_ s: String) {
        let line = s + "\n"
        let path = dir + "/log.txt"
        if let h = FileHandle(forWritingAtPath: path) {
            h.seekToEndOfFile()
            h.write(line.data(using: .utf8)!)
            h.closeFile()
        } else {
            try? line.write(toFile: path, atomically: true, encoding: .utf8)
        }
    }

    func shot(_ name: String) {
        let data = XCUIScreen.main.screenshot().pngRepresentation
        try? data.write(to: URL(fileURLWithPath: dir + "/\(name).png"))
        log("shot \(name)")
    }

    func firstHittable(_ candidates: [XCUIElement], timeout: TimeInterval = 5) -> XCUIElement? {
        let end = Date().addingTimeInterval(timeout)
        repeat {
            for c in candidates where c.exists && c.isHittable { return c }
            RunLoop.current.run(until: Date().addingTimeInterval(0.5))
        } while Date() < end
        return nil
    }

    func testFollowNewfriend() throws {
        try? FileManager.default.removeItem(atPath: dir + "/log.txt")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(3)
        shot("s1-home")

        let searchTab = firstHittable([
            app.tabBars.buttons["Search"],
            app.buttons["Search"],
        ], timeout: 3)
        if let tab = searchTab {
            tab.tap()
            log("tapped search tab via element")
        } else {
            log("search tab element not found; using coordinate")
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.308, dy: 0.935)).tap()
        }
        sleep(2)
        shot("s2-search")

        let field = firstHittable([
            app.searchFields.firstMatch,
            app.textFields.firstMatch,
        ], timeout: 3)
        if let f = field {
            f.tap()
            log("tapped search field via element")
        } else {
            log("search field element not found; using coordinate")
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.45, dy: 0.1)).tap()
        }
        sleep(1)
        app.typeText("newfriend.test")
        sleep(1)
        app.typeText("\n")
        sleep(4)
        shot("s3-results")

        let result = firstHittable([
            app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS[c] 'newfriend.test'")).firstMatch,
        ], timeout: 10)
        guard let r = result else { log("no result for newfriend.test"); XCTFail("no result"); return }
        r.tap()
        sleep(4)
        shot("s4-profile")

        let follow = firstHittable([
            app.buttons.matching(NSPredicate(format: "label == 'Follow'")).firstMatch,
        ], timeout: 10)
        guard let fb = follow else { log("no Follow button"); XCTFail("no follow button"); return }
        fb.tap()
        sleep(3)
        shot("s5-after-follow")
        log("tapped Follow")
    }
}

